SET @manifesto += N'[{"id":"observacao-documental-2tri-2026-ind-01","indicadorId":"1","lancamentoId":"6","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ O resultado permanece positivo, demonstrando a evolução de ações no que se referem a qualificação da base de clientes.\n\n▪ Ao longo do trimestre, foram realizadas novas campanhas via push, com divulgação dos produtos de loterias, promoção de jogo responsável e com foco em concurso especiais, como Mega 30 anos, Quina de São João e Loteca Especial.\n\n▪ Ao final do período do 2TRI/2026, a meta a ser alcançada de 10% da base, atingiu 78,58% (2.371.981 pessoas), representando 785,75% de alcance da meta. Contribuíram para o resultado de 78,58%, além do cronograma habitual de campanhas gerais, o aumento no volume de feriados locais (motivador de oferta personalizada aos clientes) com destaque para o Corpus Christi (não é feriado nacional) e os dias 13/06, 24/06 e 29/06 cujo alcance foi de cerca de 1,3 mil municípios. Esse contexto ampliou a sobreposição na base, fazendo com que uma parcela maior de clientes recebesse 2 ou mais notificações, conforme a regra do indicador.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"6","sha256Observacao":"7d628be3b300a98b98601761e01705e6ae92e17947d9dcba4f1e70e8ae8a1127","sha256ObservacaoSqlUtf16":"48f756f1f532fec72d5eb28224a0e6e51300f257d57f0f1829c3fa4e5ea5b6ff","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-02","indicadorId":"2","lancamentoId":"18","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ A nota é calculada considerando a pesquisa NPS baseline de 55 pontos e a meta de 2026 para redução de 20% do gap em relação à nota de referência 70, resultado em 58 (((70-55 = 15)*20%=3) → 55+3=58\n\n▪ A CAIXA Loterias alcançou 59,2 pontos de NPS no 2º trimestre de 2026, resultado 4,2 pontos superior à linha de base anterior (55,0 pontos) e equivalente a uma evolução de 7,64%.\n\n▪ A pesquisa foi realizada no mês de junho/2026, com 48.003 respostas, refletindo a percepção dos clientes dos canais digitais da CAIXA Loterias. A distribuição dos respondentes foi composta por 34.863 promotores (72,63%), 6.694 neutros (13,94%) e 6.446 detratores (13,43%).\n\n*O ajuste formal será objeto de reavaliação no âmbito da revisão do Planejamento Estratégico 2026-2030 e do Plano de Negócios 2026.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"7","';
SET @manifesto += N'sha256Observacao":"d28eec220c4f52bc373cc64ba44fb94c605742216f51303719232ef3dbd7e19e","sha256ObservacaoSqlUtf16":"42259f130f0e9b88adfd043171a39c74b10330bd4d2b59e58662c0294dc78171","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-03","indicadorId":"3","lancamentoId":"30","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ O resultado do indicador ratifica o sucesso das ações de aquisição, reativação e engajamento de clientes, além do impacto positivo das iniciativas de digitalização e personalização da jornada.\n\n▪ A média de clientes ativos nos últimos 12 meses foi de 3.040.125, um aumento de 62,16% em relação ao ano anterior (1.874.815).","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"8","sha256Observacao":"283bb69cfcf1d13bbec5e0497715593d043c9ee63ba376d24817274a9a76ee9a","sha256ObservacaoSqlUtf16":"553dd2aee35e833cf5e6c0135979d8c3285953da6a59ed7bb4b9588357378eb6","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-04","indicadorId":"4","lancamentoId":"42","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ A partir da realização da pesquisa NPS de baseline de 2025, foram definidas 22 melhorias como plano de trabalho ao longo do ano de 2026, em que para atingimento da meta anual do indicador para o ano é necessária a entrega de ao menos 06 melhorias, representando assim a meta de 25% das ocorrências apontadas.\n\n▪ As melhorias mapeadas demandam implantação junto à área de TI da CAIXA.\n\n▪ Nesse sentido, convém relembrar que a curva definida para o ano foi estruturada trimestralmente da seguinte forma:\n\n▪ 1TRI26: 4,54% - entrega de 01 melhoria do plano de trabalho de 2026;\n▪ 2TRI26: 13,64% - entrega de 03 melhorias (acumuladas) do plano de trabalho de 2026;\n▪ 3TRI26: 18,18% - entrega de 04 melhorias (acumuladas) do plano de trabalho de 2026;\n▪ 4TRI26: 251% - entrega de 06 melhorias (acumuladas) do plano de trabalho de 2026.\n\n▪ No 2º trimestre foram implementadas 03 (três) melhorias2, as quais detalhamos abaixo:\n\ni) Conferência automática completa';
SET @manifesto += N': Foi disponibilizada a conferência automática das apostas Teimosinhas3, permitindo ao cliente visualizar de forma simples o resultado de cada concurso, com indicação clara das situações “Premiada”, “Não premiada” e “Em apuração”. A melhoria trouxe mais transparência e reduziu o esforço necessário para acompanhar os resultados.\n\nii) Tela específica para Teimosinhas: Foi criada uma tela dedicada para acompanhamento das Teimosinhas, reunindo em um único local a linha do tempo dos concursos, a informação de encerramento da aposta e um resumo consolidado dos resultados. A iniciativa simplificou a navegação e facilitou o acompanhamento da aposta pelo cliente.\n\niii) Conferência automática de Teimosinhas - \"Conferir Tudo\": Foi implementada solução de conferência automática para apostas tipo Teimosinhas, passando a apresentar em uma única consulta o resultado de todos os concursos vinculados à aposta. Antes, os clientes visualizavam apenas o primeiro concurso, o que exigia consultas e conferências manuais e gerava dúvidas sobre a situação das apostas. A melhoria simplificou o acompanhamento dos resultados, reduziu etapas no processo de conferência e proporcionou uma experiência mais ágil e transparente para o apostador.\n\n1 O plano de trabalho previsto para atendimento desse indicador considera o escopo de 22 melhorias mapeadas posteriormente à definição da meta do presente indicador, conforme data da aprovação do PN 2026 da CAIXA Loterias.\n\n2 Demanda tecnológica nº 24547165.\n\n3 Apostas do tipo teimosinha são aquelas realizadas pelo apostador para o concurso atual e para o número de concursos subsequentes a escolha deste.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"9, 10","sha256Observacao":"b51e805e2ed415180ebc41d426b7cdf6bde26dfe69b0fc79823581aee8f4479e","sha256ObservacaoSqlUtf16":"0480a398f942f2feca8c12f7ab4a3c2be584a9d4dd75446bee61445332e58985","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-05","indicadorId":"5","lancamentoId":"54","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ O desempenho vem mantendo o patamar mensal de arrecadação próximo ao orçado, em que ações comerciais e de engajamento de clientes vem sendo desenvolvidas para incremento dos resultados nos próximos períodos, como o concurso especial Loteca Especial e Mega 30 anos, além de outras estratégias comerciais.\n\n▪ O referido indicador fará parte do escopo de revisão do Planejamento Estratégico 2026-2030 e do Plano de Negócios 2026.","fonteDocumental":"I';
SET @manifesto += N'nforme DILOT/GERIN nº 0056/2026","paginasDocumento":"10","sha256Observacao":"057834931871b0b259dbd028cb8c96a46c2a5aaed834e6e5a1234d691f8857de","sha256ObservacaoSqlUtf16":"45f505dc4527aac594ab6974e948906cfb8f9abf1ec722c3bc8468b90551ddcb","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-06","indicadorId":"6","lancamentoId":"66","versaoLancamento":1,"statusEsperado":"Não iniciado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ Abril / 2026\n  Despesa de Pessoal e Administrativa: 89.043.444,39\n  Receitas Líquidas: 800.062.366,68\n  IEO: 11,13%\n\n▪ Maio / 2026\nDespesa de Pessoal e Administrativa: 111.918.855,78\n  Receitas Líquidas: 1.004.116.152,00\n  IEO: 11,15%\n\n▪ Junho / 2026\n Despesa de Pessoal e Administrativa: R$ 133.544.533,40\n Receitas Líquidas: R$ 1.198.234.728,56\n IEO: 11,15%\n\n▪ O referido indicador fará parte do escopo de revisão do Planejamento Estratégico 2026-2030 e do Plano de Negócios 2026.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"11","sha256Observacao":"6531773c106bf7c9b455c6528d966741a27e5459740e3fc8b56f1ea0cc76f555","sha256ObservacaoSqlUtf16":"2396b0504a168d7648fc309158df4d3b4cf0f8cfa17944c9431d163b4a85a327","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-07","indicadorId":"7","lancamentoId":"78","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ Em abril/26 a companhia obteve lucro líquido de R$ 448,1 milhões, receita total de R$ 887,0 milhões e despesas de R$ 438,8 milhões.\n\n▪ Em maio/26 a companhia obteve lucro líquido de R$ 562,6 milhões, receita total de R$ 1.113,4 milhões e despesas de R$ 550,7 milhões.\n\n▪ Em junho/26 a companhia obteve lucro líquido de R$ 671,2 milhões, receita total de R$ 1.328,6 milhões e despesas de R$ 657,4 milhões.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"12","sha256Observacao":"2f807cc1581f7db9e67534eee2018ef270f1afac2cf8a3fe39b2ccd940b5d021","sha256ObservacaoSqlUtf16":"542bdf812185008ea2c58f1d8060f7bf22f30fdcea42e052e41e91608a0d0c30","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce0';
SET @manifesto += N'4e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-08","indicadorId":"8","lancamentoId":"90","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ O desempenho dos canais digitais apresentou crescimento acima do esperado, quando comparado com o mesmo período do ano de 2025, registrando ao final do 2TRI2026 realizado de 29,02%, que corresponde a arrecadação de R$ 3,538 bilhões, e alcance da meta em 103,72%. Em 2025, no mesmo período foi registrada arrecadação de R$ 2,658 bilhões.\n\n▪ O resultado reforça a maturidade das iniciativas digitais, a maior adesão dos clientes aos canais eletrônicos e a efetividade das estratégias de estímulo à migração digital.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"12","sha256Observacao":"55c753251a29dedaf745035360d42837573eee5dbebfb497d9f4fb03bdafed57","sha256ObservacaoSqlUtf16":"619264633db5663a1acdc7ac4981452568f9ccf738aa1f8a20738ab6c5820011","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-09","indicadorId":"9","lancamentoId":"102","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"Cabe relembrar que a seguinte curva de meta foi definida para 2026:\n▪ 1TRI26: 61%;\n▪ 2TRI26: 62%;\n▪ 3TRI26: 63%;\n▪ 4TRI26: 65%.\n\n▪ A meta estabelecida para o período considerou a projeção orçamentária prevista no Plano de Dispêndios Globais de 2026 da Companhia.\n\n▪ Ao final de junho de 2026, o acumulado do indicador atingiu R$ 2,262 bilhões, superando a trajetória prevista para o exercício. O resultado evidencia a consolidação do Pix nos canais eletrônicos e demonstra a manutenção da preferência dos clientes por esse meio de pagamento nas compras digitais.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"13","sha256Observacao":"378878688a21ec75663c4cde8a646885e33ca3cde6e8d55386cbeb18c85a5de8","sha256ObservacaoSqlUtf16":"86b55b4e85a211295126d0c9e4049c6eda4892d583e811f14cdf3d3cb445a618","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoRefer';
SET @manifesto += N'encia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-10","indicadorId":"10","lancamentoId":"114","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ Ao longo do 2TRI/26, a funcionalidade de Registro de Aposta (em ambiente de desenvolvimento) foi finalizada, a partir das regras de negócio definidas pela Superintendência Nacional Comercial de Loterias (SUCOL) e do Desenvolvimento realizado pela área de Tecnologia no Sistema Plataforma de Loterias e Jogos (SIPLX) da CAIXA Loterias, conforme telas do sistema que evidenciam esta entrega.\n\n▪ Considerando a complexidade técnica das funcionalidades e integrações necessárias para a operação em produção, a evolução do indicador será objeto de reavaliação no âmbito da revisão do PEI 2026-2030 e do PN 2026.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"14","sha256Observacao":"33025d4b7da9125b088ef62792ba376906de25a2798c1c116cea092732072d60","sha256ObservacaoSqlUtf16":"c9a83e570c18d2daa681ccbe38c74bceaf6159ed1bb1a24c5ac4681fc8acb167","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-11","indicadorId":"11","lancamentoId":"126","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n▪ 1TRI26: 35% - Realização de Consulta Pública de Informações – RFI (Request for Information);\n▪ 2TRI26: 70% - Realização de Consulta Pública de Propostas – RFP (Request for Proposal);\n▪ 3TRI26: 85% - Iniciação da Fase Seleção;\n▪ 4TRI26: 100% - Contrato assinado com fornecedor.\n\n▪ A curva de meta previa a realização de RFP, que não ocorreu visto que em MAI/2026 a CAIXA Loterias realizou a contratação do GARTNER, e iniciou o alinhamento de forma a aprofundar a estratégia de Tecnologia e ratificar os caminhos de contratação a serem adotados para ampliação da capacidade de entrega de soluções para a CAIXA Loterias, considerando os subsídios recebidos em RFI (request for information).\n\n▪ Dessa forma, no que se refere à proposta do indicador, foi realizada a compilação dos insumos do RFI, bem como rodadas de reuniões com fornecedores, e estão sendo realizados os estudos dos modelos de contratação adequados, que consubstanciarão as propostas de contratação c';
SET @manifesto += N'om prosseguimento no 3º trimestre, no qual devem ser realizados RFP (request for proposal), conforme o caso.\n\n▪ A coleta dos insumos de mercado, e a revisão dos modelos a serem adotados é fundamental para permitir a continuidade das iniciativas de forma coordenada na companhia, otimizando esforços e frentes de atuação. Em JUL/2026 está prevista a realização de workshop presencial junto a Gartner e CAIXA Loterias, a partir do qual haverá o aprofundamento e consolidação das informações, bem a configuração do desenho a ser seguido em relação às contratações.\n\n▪ No projeto de desenvolvimento da Nova Plataforma de Loterias, em JUN/2026 foi realizada a demanda de contratação de 23 profissionais da fábrica de software fornecedor Spassu, com o objetivo de ampliação da capacidade de desenvolvimento da equipe atual permitindo criar paralelismo das SQUAD e acelerar as entregas do projeto, cujas contratações efetivas devem ocorrer ao longo do 3º tri.\n\n▪ Com essas contratações e aporte dos profissionais, haverá o atingimento do indicador, em que pese seu status atual de aquém do esperado no 2TRI/2026.\n\n▪ Cabe mencionar ainda sobre a consultoria de tecnologia, definida na Estratégia de Tecnologia da empresa, que auxiliará no aprofundamento das discussões em relação as ações de longo prazo da companhia, após a consolidação das contribuições do RFI, foi formatado TR para solicitação de propostas. Este TR foi submetido a revisão inicial do Gartner, cujas contribuições estão em andamento, para prosseguimento junto ao mercado no 3º trimestre.\n\n▪ Ainda, na frente de CRM (Customer Relationship Manegement)6, ao longo do período foram realizadas etapas do processo de pesquisa de mercado para contratação de uma plataforma de CRM.\n\n▪ Em paralelo, a Controladora CAIXA aprovou em rito de governança próprio a contratação da empresa Salesforce, contemplado em seu objeto plataforma de CRM para a CAIXA. Nesse sentido, foram iniciados alinhamentos para uso pela CAIXA Loterias, via Termo Ajuste Operacional (TAO).\n\n6 CRM significa Customer Relationship Management, em português Gestão de Relacionamento com o Cliente. Refere-se a uma plataforma de gestão do relacionamento com clientes, voltada à integração de dados, personalização de interações, apoio a campanhas e melhoria da experiência do cliente ao longo de sua jornada.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"14, 15","sha256Observacao":"31068469d07177643c26d8e974ffdfd63819a4e5d92f08455873f0fb1235a031","sha256ObservacaoSqlUtf16":"e3e9155baef3a6f73fa5f0ff9e3acda7b1d699ccfd1843e08062d78fb0dda868","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observ';
SET @manifesto += N'acao-documental-2tri-2026-ind-12","indicadorId":"12","lancamentoId":"138","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"As iniciativas previstas no Plano de Ação seguem em andamento em toda a CAIXA Loterias. A pesquisa GPTW está programada para outubro de 2026.\n\nPonto de Controle semanal para acompanhamento, monitoramento e mensuração dos resultados obtidos até momento.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"16","sha256Observacao":"64635b7bde3c588b51370e4ff7fa88a0527cd75269e4d963a9e381ec05bb16e5","sha256ObservacaoSqlUtf16":"1258b9d497f97052f23ba3db1f37ad1550d29097628cb8e8586638d4e3aba16b","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-13","indicadorId":"13","lancamentoId":"150","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ abr/26: 16 mulheres de 43 gestores | 37,21%\n▪ mai/26: 16 mulheres de 45 Gestores | 35,56%\n▪ jun/26: 19 mulheres de 46 Gestores | 41,3%\n\nO referido indicador fará parte do escopo de revisão do Planejamento Estratégico 2026-2030 e do Plano de Negócios 2026.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"17","sha256Observacao":"0257b4e33e3d9e1d6debb8d1e534c817e0f41450167aeb5c26daa5578ef9bd44","sha256ObservacaoSqlUtf16":"b06d728c57319bb20574d77d21b71546b8f7f2b7b5b02b2e935a349899f77a39","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-14","indicadorId":"14","lancamentoId":"162","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ abr/26: 11 de 43 gestores\n▪ mai/26: 12 de 45 Gestores\n▪ jun/26: 11 de 46 gestores\n\nO referido indicador fará parte do escopo de revisão do Planejamento Estratégico 2026-2030 e do Plano de Negócios 2026.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"17","sha256Observacao":"7d28f4143098ff14725697f9a5d72af2553da7e8850118f6b2a8424fb58a510f","sha256ObservacaoSqlUtf16":"f4c6bd6a63b53357195ed07e06c1fe7db8aa129c19d89018764c758eab9222d6","sha';
SET @manifesto += N'256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-15","indicadorId":"15","lancamentoId":"174","versaoLancamento":2,"statusEsperado":"Retificado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ Meta estipulada em 90% para que os empregados realizem os dois cursos propostos na trilha de desenvolvimento, quais sejam: Certificação do Jogo Responsável e Certificação CAIXA Digital 2.\n\n▪ Até 30/06/2026, 177 empregados no total de 183 empregados realizaram os cursos.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"18","sha256Observacao":"e2cacd472550dd3a7689a017044b53135031767fbe055b7f0246a6271f020457","sha256ObservacaoSqlUtf16":"4cddd59f2aaa5c0a41a95da4d0533a7fe5838755d6377c61b59a27039b9d8de3","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-16","indicadorId":"16","lancamentoId":"186","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n▪ 1TRI26: 0%;\n▪ 2TRI26: 50% - 1ª iniciativa realizada;\n▪ 3TRI26: 50% (acumulado de 50% considerando apenas a meta do 2TRI26);\n▪ 4TRI26: 100% - 2ª iniciativa realizada.\n\n▪ Os projetos encontram-se em fase de prospecção e estruturação, para posterior encaminhamento em rito de governança da CAIXA Loterias.\n\n▪ Como desdobramento do indicador ao longo do 2TRI/2026, foi construída a primeira versão da norma de patrocínios da CAIXA Loterias, a qual seguirá em rito de governança, com previsão de publicação no 3TRI/2026.\n\n▪ No âmbito da Companhia, foram recepcionadas propostas alinhadas ao desenvolvimento socioambiental, via Portal de Patrocínios da CAIXA, canal utilizado para recepção de propostas de projetos, o qual serão avaliadas nos próximos períodos, à luz da norma da Companhia (em construção).","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"18, 19","sha256Observacao":"00e2f5face301f0e991cb9a8087c32af2b3b375cb1a147c7c6ec1a0d201b6e7d","sha256ObservacaoSqlUtf16":"18d851d715f642f15b45c35fe4254ab4ded3d30ae41747aeac6c69349e764e60","sha256DocumentoDeclarado":"7a357535e11e562a1';
SET @manifesto += N'd3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-17","indicadorId":"17","lancamentoId":"198","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ A meta estabelecida para o período considerou a projeção orçamentária prevista no Plano de Dispêndios Globais da Companhia de 2026.\n\n▪ Cabe relembrar a seguinte curva de meta definida para 2026 com relação ao presente indicador:\n▪ 1TRI26: R$ 2.143,0 milhões;\n▪ 2TRI26: R$ 4.545,1 milhões;\n▪ 3TRI26: R$ 7.165,1 milhões;\n▪ 4TRI26: R$ 10.452,8 milhões.\n\n▪ Valores aferidos referentes ao 2º trimestre/2026 (acumulados):\n\nRepasses Abril/2026: R$ 3.035.017.772,90\nRepasses Maio/2026: R$ 3.837.408.558,29\nRepasses Junho/26: R$ 4.615.037.076,03","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"19, 20","sha256Observacao":"4f996f2b994a711f607225dee55fc54d8b8379bee1404b021d7ab00e9cc6ae25","sha256ObservacaoSqlUtf16":"529a1502aae85b42f2464061efd691d9494f26df216915640527f23fd34f762d","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-18","indicadorId":"18","lancamentoId":"210","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ No contexto do objetivo do PEI “Nível 3 RGF-WLA – Executar ações de melhoria para os 10 elementos”, registra-se que, no 1TRI26, foi concluída a instituição do Fórum de Jogo Responsável, iniciativa que materializa o elemento “Engajamento das Partes Interessadas” ao reunir representantes para, em encontros semestrais, acompanhar o Programa, colher contribuições e preocupações e promover melhorias.\n\n▪ No 2TRI26, até o momento, foi realizada ação sobre o elemento 8 - ORIENTAÇÃO SOBRE TRATAMENTO, tendo sido revista a relação de entidades indicadas para tratamento e atendimento ao público afetado.\n\n▪ Há outras ações em execução, que avançam sobre os demais 8 elementos do Programa, e seu cronograma decorre de sequenciamento técnico, dependências entre entregas e cadência operacional de implementação, razão pela qual o atendimento ocorrerá em curva ao longo do exercício, conforme esperado para o período: 1 elemento no 1º trimestre; 2 elementos no 2º; 5 element';
SET @manifesto += N'os no 3º; e 10 elementos no 4º trimestre, de forma cumulativa, mantendo a trajetória de evolução planejada do Programa. Finalizadas 2 das ações de 10 previstas para o ano. Desse modo, tem-se que o realizado no mês de abril cumpre o esperado para o período.\n\n▪ Jogo Responsável, com disponibilização de autoavaliação e direcionamento para instituições de apoio e tratamento (Elemento 8 – Tratamento do Jogador); a realização de treinamento corporativo sobre Jogo Responsável para empregados e Alta Administração (Elemento 2 – Empregados); a capacitação na metodologia GamGard para equipes responsáveis pelo desenvolvimento e revisão de produtos e canais digitais (Elemento 4 – Design de Jogos e Elemento 5 – Jogos Remotos); e a evolução dos trabalhos de definição, aperfeiçoamento e consolidação de indicadores de monitoramento do Programa (Elemento 10 – Relatórios e Medição). Paralelamente, foram realizadas atividades de revisão, atualização e consolidação de evidências, acompanhamento do plano de ação corporativo e alinhamento com as áreas responsáveis pelos requisitos da certificação RGF/WLA. Dessa forma, o Programa avançou sobre os Elementos 2, 3, 4, 5, 8 e 10, mantendo trajetória compatível com o cronograma de evolução previsto para o exercício e superando o quantitativo mínimo esperado para o período.\n\n▪ Há outras ações em execução, que avançam sobre os demais elementos do Programa, e seu cronograma decorre de sequenciamento técnico, dependências entre entregas e cadência operacional de implementação, razão pela qual o atendimento ocorrerá em curva ao longo do exercício, conforme esperado para o período: 1 elemento no 1º trimestre; 2 elementos no 2º; 5 elementos no 3º; e 10 elementos no 4º trimestre, de forma cumulativa, mantendo a trajetória de evolução planejada do Programa.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"20, 21","sha256Observacao":"ce84b4a7c43746bc821b4168dd335098ff232c17aa635cb4df6b5d32901a984e","sha256ObservacaoSqlUtf16":"1a48b820801b19a5f7d36499fc862d468f66212084ec045c5914ff9da7694432","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-19","indicadorId":"19","lancamentoId":"222","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ A seguinte curva de meta foi definida para 2026 com relação ao presente indicador:\n▪ 1TRI26: 0%;\n▪ 2TRI26: 0,05%; (R$ 652,7 mil);\n▪ 3TRI26: 0,10% (R$ 1.305,4 mil - valor acumulado, considerando o realizado do 2TRI26 e 3TRI26).\n▪ 4TRI26: 0,33% (R$ 4.307,9 mil7 - valor acumulado, considerando o rea';
SET @manifesto += N'lizado do 2TRI26, 3TRI26 e 4TRI26).\n\n▪ Como desdobramento do indicador ao longo do 2TRI/2026, foi construída a primeira versão da norma de patrocínios da CAIXA Loterias, a qual seguirá em rito de governança, com previsão de publicação no 3TRI/2026.\n\n▪ No âmbito da Companhia, foram recepcionadas propostas alinhadas ao desenvolvimento socioambiental, via Portal de Patrocínios da CAIXA, canal utilizado para recepção de propostas de projetos, o qual serão avaliadas nos próximos períodos, à luz da norma da Companhia (em construção).\n\n7 Valor projetado conforme orçamento 2026, que prevê Lucro Líquido em R$ 1.305,4 milhões.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"22","sha256Observacao":"46adf7576b81bd2b55c943ce62c2602c0900ec4a7b531fd7c5eb9bb3b6c94135","sha256ObservacaoSqlUtf16":"f0707ae60349f800a7812040306e19cc96232df29672ae4b7c2d7c32389e23a9","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-20","indicadorId":"20","lancamentoId":"234","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ O Relatório Sorte em Números foi publicado no site em 17 junho de 2026 8, que consolida dados de repasse social com linguagem acessível e foco em transparência pública ao público apostador.\n\n8 Relatório disponível no seguinte endereço: https://www.caixa.gov.br/Downloads/caixa-loterias/Relatorio-Sorte-em-Numeros-2025.pdf","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"23","sha256Observacao":"4f664998b7e3c1f22e9e092fdd356abe5f88a6f091065e41aab7e6f2c66675cf","sha256ObservacaoSqlUtf16":"72e6ce074ad358817275b8a29efa66b43397881d3d292ccf28181d214229eac7","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-21","indicadorId":"21","lancamentoId":"246","versaoLancamento":1,"statusEsperado":"Homologado","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ Foi apurado que 123 funcionários, de 184, realizaram/participaram de ao menos 2 ações de disseminação de JR até 30/06/2026, correspondendo à 66,85%:\n\n- Curso na Universidade CAIXA;\n\n- Capacitação em Jogo Responsável, realizada em maio/2026 na Universidade';
SET @manifesto += N' CAIXA;\n\n- Capacitação em Design de Jogos - GamGard - realizado em junho/2026 na Universidade CAIXA.\n\n▪ Outras ações referentes ao Jogo Responsável serão realizadas no decorrer no ano de 2026. Por se tratar de objetivo a ser realizado e concluído ao longo de 2026, o percentual realizado e o esperado no 2ºTRI26 estão dentro do planejamento.","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"23, 24","sha256Observacao":"209ad33af4ff468f22ef0d353ba86485ff6cd94f9c7db55bbb0f3cd3a3e0b0a6","sha256ObservacaoSqlUtf16":"aadb8fc248aa571d404d32ab9334fb6be869c51034ba9cd164f9c74bdead2e23","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-22","indicadorId":"22","lancamentoId":"258","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"▪ Cenário com Lotex:\n\nA seguinte curva de meta foi definida para 2026, considerando o comportamento de dados do realizado de arrecadação em 2025:\n\n▪ 1TRI26: arrecadação via ecossistema em 1º TR/2025 representou 0,90% do total. Acrescidos 10%, a meta para o período é de 0,99%;\n▪ 2TRI26: arrecadação via ecossistema em 2TRI/2025 representou 0,78% do total. Acrescidos 10%, a meta para o período é de 0,86%;\n▪ 3TRI26: arrecadação via ecossistema em 3TRI/2025 representou 0,74% do total. Acrescidos 10%, a meta para o período é de 0,81%;\n▪ 4TRI26: arrecadação via ecossistema em 4TRI/2025 representou 0,65% do total. Acrescidos 10%, a meta para o período é de 0,72%.\n\nAo longo do período do 2TRI26, o desempenho de vendas registrou realizado de 0,61%, representando R$ 74,1 milhões de arrecadação da Loteria Instantânea Exclusiva - Lotex, frente R$ 12,192 bilhões de arrecadação total, com atingimento de 71,12% da meta.\n\nCom foco na ampliação da oferta da Lotex e em alinhamento às iniciativas estratégicas, os seguintes projetos estão sendo conduzidos:\n\n• Programa de Afiliados Instantânea CAIXA Digital: ampliar a divulgação e a comercialização dos bilhetes da Lotex no formato digital, por meio das Unidades Lotéricas como afiliadas à plataforma oficial da CAIXA Loterias;\n\n• Instantânea CAIXA Compre Aqui: tem como finalidade ampliar os canais físicos de venda da Lotex, mediante a vinculação de Pontos de Venda a Unidades Lotéricas, que contribuirá para aumentar a comercialização do produto ao apostador.\n\nCujos lançamentos estão previstos para o 3TRI/2026.\n\nAdicionalmente, menciona-se que a Lotex aguarda autorização da Secretaria de Prêmios e Apostas, vinculada ao Ministério da Fazenda, sobre a prorrogação da outorga para a CAIX';
SET @manifesto += N'A Loterias continuar comercializando o produto.\n\nCabe destacar ainda que a meta projetada para o presente indicador considerou o lançamento de Apostas de Quota Fixa, cuja implementação permanece em avaliação, razão pela qual a premissa será reavaliada no âmbito da revisão do PEI 2026-2030\n\nCenário com Lotex e ferramenta do Marketplace9:\n\nA seguinte curva de meta foi definida para 2026, considerando o comportamento de dados do realizado de arrecadação em 2025, somando Lotex e Marketplace:\n\n▪ 1TRI26: arrecadação via ecossistema em 1º TR/2025 representou 3,42% do total. Acrescidos 10%, a meta para o período é de 3,76%;\n▪ 2TRI26: arrecadação via ecossistema em 2TRI/2025 representou 3,27% do total. Acrescidos 10%, a meta para o período é de 3,60%;\n▪ 3TRI26: arrecadação via ecossistema em 3TRI/2025 representou 3,32% do total. Acrescidos 10%, a meta para o período é de 3,65%;\n▪ 4TRI26: arrecadação via ecossistema em 4TRI/2025 representou 3,46% do total. Acrescidos 10%, a meta para o período é de 3,80%.\n\nAo fechamento do período 2TRI2026, o desempenho de vendas registrou realizado em 4,22%, com alcance da meta em 117,13%. As iniciativas do período reforçaram a atuação da Rede Lotérica via plataforma de comercialização de bolão online, Marketplace, além do resultado da Lotex, fatores que contribuíram para o resultado apurado na prestação de contas do mês.\n\nO referido indicador fará parte do escopo de revisão do Planejamento Estratégico 2026-2030 e do Plano de Negócios 2026.\n\n9 Marketplace - plataforma de comercialização de bolão online","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"24, 25, 26","sha256Observacao":"b72df0ecd6dc67e540a056ef671564b1b855ba3054d8f684e48946795c674594","sha256ObservacaoSqlUtf16":"d0642b9c855ca29fde2076732c2418ffe11e9b87227e726973d068e687a419b1","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"},{"id":"observacao-documental-2tri-2026-ind-23","indicadorId":"23","lancamentoId":"270","versaoLancamento":1,"statusEsperado":"Em preenchimento","competencia":"2026-06","ano":2026,"mes":6,"tipoObservacao":"OBSERVACAO_AREA_INFORME_TRIMESTRAL","observacao":"A seguinte curva de meta foi definida para 2026, considerando o comportamento de dados do realizado de arrecadação em 2025:\n▪ 1TRI26: 100,50%;\n▪ 2TRI26: 101,00%;\n▪ 3TRI26: 101,50%;\n▪ 4TRI26: 102,00%.\n\nNos dados acumulados até JUN/26, a arrecadação da Rede Lotérica atingiu 98,8%, com alcance da meta 97,84%.\n\nEm análise dos dados, observa-se que, no recorte específico de JUN/26, o canal físico apresentou variação de 4,93%, em relação ao mesmo mês de 2025, em contexto influenciado pela dinâmica do comércio durante a C';
SET @manifesto += N'opa do Mundo 2026 e pela maior preferência dos clientes pelos canais digitais.\n\nEm função da dinâmica do comércio durante a Copa do Mundo 2026, observou-se impacto nos resultados de arrecadação do portfólio de loterias especialmente no canal físico, sendo observada a preferência do cliente para compras por meio dos canais digitais10, fator que contribui para a leitura do comportamento observado no trimestre.\n\n10 https://www.ecommercebrasil.com.br/noticias/copa-do-mundo-desloca-consumo-para-o-online-e-pressiona-lojas-fisicas-aponta-icva","fonteDocumental":"Informe DILOT/GERIN nº 0056/2026","paginasDocumento":"26, 27","sha256Observacao":"819d26e280d645452f55022d65ac2287207e385dc0413935f1a1b303a77699e1","sha256ObservacaoSqlUtf16":"ebcf343951f40e4fc26fe349225c069a6491da6762cb8409d091d539b67016d1","sha256DocumentoDeclarado":"7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f","sha256ArquivoFisico":"d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446","documentoReferencia":"C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf","origemRegistro":"20261028_001_observacoes_documentais_2tri_2026.sql"}]';
  IF ISJSON(@manifesto)<>1 THROW 53503,N'Manifesto incorporado invalido.',1;

  DECLARE @carga TABLE(
    id NVARCHAR(100) PRIMARY KEY,lancamento_id NVARCHAR(100),indicador_id NVARCHAR(100),competencia NVARCHAR(40),
    ano INT,mes INT,versao_lancamento INT,status_esperado NVARCHAR(100),tipo_observacao NVARCHAR(100),observacao NVARCHAR(MAX),
    fonte_documental NVARCHAR(500),paginas_documento NVARCHAR(100),sha256_observacao CHAR(64),
    sha256_observacao_sql_utf16 CHAR(64),sha256_documento_declarado CHAR(64),sha256_arquivo_fisico CHAR(64),
    documento_referencia NVARCHAR(500),origem_registro NVARCHAR(255)
  );
  INSERT @carga
  SELECT id,lancamentoId,indicadorId,competencia,ano,mes,versaoLancamento,statusEsperado,tipoObservacao,observacao,
         fonteDocumental,paginasDocumento,sha256Observacao,sha256ObservacaoSqlUtf16,sha256DocumentoDeclarado,
         sha256ArquivoFisico,documentoReferencia,origemRegistro
  FROM OPENJSON(@manifesto) WITH(
    id NVARCHAR(100) '$.id',lancamentoId NVARCHAR(100) '$.lancamentoId',indicadorId NVARCHAR(100) '$.indicadorId',
    competencia NVARCHAR(40) '$.competencia',ano INT '$.ano',mes INT '$.mes',versaoLancamento INT '$.versaoLancamento',
    statusEsperado NVARCHAR(100) '$.statusEsperado',tipoObservacao NVARCHAR(100) '$.tipoObservacao',
    observacao NVARCHAR(MAX) '$.observacao',fonteDocumental NVARCHAR(500) '$.fonteDocumental',
    paginasDocumento NVARCHAR(100) '$.paginasDocumento',sha256Observacao CHAR(64) '$.sha256Observacao',
    sha256ObservacaoSqlUtf16 CHAR(64) '$.sha256ObservacaoSqlUtf16',sha256DocumentoDeclarado CHAR(64) '$.sha256DocumentoDeclarado',
    sha256ArquivoFisico CHAR(64) '$.sha256ArquivoFisico',documentoReferencia NVARCHAR(500) '$.documentoReferencia',
    origemRegistro NVARCHAR(255) '$.origemRegistro'
  );

  IF (SELECT COUNT(*) FROM @carga)<>23
    OR (SELECT COUNT(DISTINCT indicador_id) FROM @carga)<>23
    OR (SELECT COUNT(DISTINCT lancamento_id) FROM @carga)<>23
    OR (SELECT COUNT(DISTINCT sha256_observacao) FROM @carga)<>23
    THROW 53504,N'Manifesto deve conter exatamente 23 identidades, lancamentos e hashes unicos.',1;
  IF EXISTS(
    SELECT 1 FROM @carga
    WHERE tipo_observacao<>@tipo OR competencia<>N'2026-06' OR ano<>2026 OR mes<>6 OR origem_registro<>@migration
      OR fonte_documental<>N'Informe DILOT/GERIN nº 0056/2026'
      OR sha256_documento_declarado<>'7a357535e11e562a1d3abc43c419ef8b585316743ce04e34e287bdd45cd25d4f'
      OR sha256_arquivo_fisico<>'d4b59d51865c68b82a08d5e5e6bf6705edfea8651e5678bae2326fdee7c28446'
      OR documento_referencia<>N'C:/Users/jonat/Downloads/sistema/00.Informe DILOT_GERIN_0056_2026_Monitoramento_PEI_PNI 2TRI26_ass.pdf'
  ) THROW 53505,N'Identidade ou metadados documentais da carga invalidos.',1;
  IF EXISTS(
    SELECT 1 FROM @carga
    WHERE LOWER(CONVERT(VARCHAR(64),HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),observacao)),2))<>sha256_observacao_sql_utf16
  ) THROW 53506,N'Hash SQL UTF-16 da observacao literal divergente.',1;

  DECLARE @marAntes NVARCHAR(MAX)=(
    SELECT d.* FROM dbo.lancamentos_observacoes_documentais d
    WHERE d.competencia=N'2026-03' AND d.ano=2026 AND d.mes=3
    ORDER BY d.id FOR JSON PATH,INCLUDE_NULL_VALUES
  );
  DECLARE @marHashAntes VARBINARY(32)=HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),@marAntes));
  IF (SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais WHERE competencia=N'2026-03' AND ano=2026 AND mes=3)<>23
    OR EXISTS(
      SELECT 1 FROM dbo.lancamentos_observacoes_documentais
      WHERE competencia=N'2026-03' AND ano=2026 AND mes=3
        AND (origem_registro<>@migration1tri OR substitui_observacao_id IS NOT NULL)
    ) THROW 53507,N'Snapshot documental do 1TRI incompativel.',1;

  DECLARE @existentes INT=(SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais WHERE origem_registro=@migration);
  DECLARE @junExistentes INT=(SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais WHERE competencia=N'2026-06' AND ano=2026 AND mes=6);
  DECLARE @totalExistentes INT=(SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais);
  IF @existentes NOT IN(0,23)
    THROW 53508,N'Aplicacao parcial detectada; nenhuma linha sera acrescentada.',1;
  IF @junExistentes<>@existentes OR @totalExistentes<>23+@existentes
    THROW 53509,N'Conflito com carga documental preexistente ou total documental inesperado.',1;

  IF EXISTS(
    SELECT 1 FROM @carga c
    LEFT JOIN dbo.lancamentos l ON l.id=c.lancamento_id AND l.indicador_id=c.indicador_id
      AND l.competencia=c.competencia AND l.ano=c.ano AND l.mes=c.mes
      AND l.versao_atual=c.versao_lancamento AND l.status=c.status_esperado
    WHERE l.id IS NULL
  ) THROW 53510,N'Lancamento, competencia, versao ou status divergiu do manifesto.',1;

  IF @existentes=23 AND EXISTS(
    SELECT 1 FROM @carga c FULL JOIN (
      SELECT * FROM dbo.lancamentos_observacoes_documentais WHERE origem_registro=@migration
    ) d ON d.id=c.id
    WHERE c.id IS NULL OR d.id IS NULL OR d.lancamento_id<>c.lancamento_id OR d.indicador_id<>c.indicador_id
      OR d.competencia<>c.competencia OR d.ano<>c.ano OR d.mes<>c.mes OR d.versao_lancamento<>c.versao_lancamento
      OR d.tipo_observacao<>c.tipo_observacao OR d.observacao<>c.observacao OR d.fonte_documental<>c.fonte_documental
      OR d.paginas_documento<>c.paginas_documento OR d.sha256_observacao<>c.sha256_observacao
      OR d.sha256_documento_declarado<>c.sha256_documento_declarado OR d.sha256_arquivo_fisico<>c.sha256_arquivo_fisico
      OR d.documento_referencia<>c.documento_referencia OR d.substitui_observacao_id IS NOT NULL
  ) THROW 53511,N'Reexecucao encontrou conteudo documental divergente.',1;
  IF @existentes=0 AND EXISTS(
    SELECT 1 FROM @carga c JOIN dbo.lancamentos_observacoes_documentais d
      ON d.id=c.id OR (d.lancamento_id=c.lancamento_id AND d.versao_lancamento=c.versao_lancamento
      AND d.competencia=c.competencia AND d.tipo_observacao=c.tipo_observacao)
  ) THROW 53512,N'Conflito de identidade com carga documental preexistente.',1;

  DECLARE @lancamentos_antes TABLE(id NVARCHAR(100) PRIMARY KEY,fingerprint VARBINARY(32));
  INSERT @lancamentos_antes
  SELECT l.id,HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),
    CAST(N'' AS NVARCHAR(MAX))+ISNULL(l.id,N'<NULL>')+N'|'+ISNULL(l.indicador_id,N'<NULL>')+N'|'+ISNULL(l.competencia,N'<NULL>')+
    N'|'+ISNULL(CONVERT(NVARCHAR(20),l.ano),N'<NULL>')+N'|'+ISNULL(CONVERT(NVARCHAR(20),l.mes),N'<NULL>')+
    N'|'+ISNULL(l.trimestre,N'<NULL>')+N'|'+ISNULL(l.plano,N'<NULL>')+N'|'+ISNULL(l.pilar,N'<NULL>')+
    N'|'+ISNULL(l.unidade_apuradora,N'<NULL>')+N'|'+ISNULL(l.diretoria_responsavel,N'<NULL>')+
    N'|'+ISNULL(l.dados_entrada_json,N'<NULL>')+N'|'+ISNULL(l.resultado_calculado,N'<NULL>')+
    N'|'+ISNULL(l.resultado_oficial,N'<NULL>')+N'|'+ISNULL(l.meta_referencia,N'<NULL>')+
    N'|'+ISNULL(l.percentual_atingido,N'<NULL>')+N'|'+ISNULL(l.situacao,N'<NULL>')+N'|'+ISNULL(l.status,N'<NULL>')+
    N'|'+ISNULL(l.observacao_unidade,N'<NULL>')+N'|'+ISNULL(l.referencia_evidencia,N'<NULL>')+
    N'|'+ISNULL(l.evidencia_id,N'<NULL>')+N'|'+CONVERT(NVARCHAR(20),l.versao_atual)+
    N'|'+ISNULL(l.usuario_responsavel,N'<NULL>')+N'|'+ISNULL(l.created_at,N'<NULL>')+N'|'+ISNULL(l.updated_at,N'<NULL>')
  )) FROM dbo.lancamentos l JOIN @carga c ON c.lancamento_id=l.id;

  DECLARE @homologacoesAntes NVARCHAR(MAX)=(SELECT h.* FROM dbo.homologacoes h JOIN @carga c ON c.lancamento_id=h.lancamento_id ORDER BY h.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @evidenciasAntes NVARCHAR(MAX)=(SELECT e.* FROM dbo.evidencias e JOIN @carga c ON c.lancamento_id=e.lancamento_id ORDER BY e.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @retificacoesAntes NVARCHAR(MAX)=(SELECT r.* FROM dbo.retificacoes r JOIN @carga c ON c.lancamento_id=r.lancamento_id ORDER BY r.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @reaberturasAntes NVARCHAR(MAX)=(SELECT s.* FROM dbo.solicitacoes_reabertura s JOIN @carga c ON c.lancamento_id=s.lancamento_id ORDER BY s.id FOR JSON PATH,INCLUDE_NULL_VALUES);
  DECLARE @auditoriaAntes NVARCHAR(MAX)=(SELECT a.* FROM dbo.auditoria a JOIN @carga c ON c.lancamento_id=a.entidade_id WHERE a.entidade=N'lancamentos' ORDER BY a.id FOR JSON PATH,INCLUDE_NULL_VALUES);

  IF @existentes=0
  BEGIN
    INSERT dbo.lancamentos_observacoes_documentais(
      id,lancamento_id,indicador_id,competencia,ano,mes,versao_lancamento,tipo_observacao,observacao,
      fonte_documental,paginas_documento,sha256_observacao,sha256_documento_declarado,sha256_arquivo_fisico,
      documento_referencia,substitui_observacao_id,origem_registro
    )
    SELECT id,lancamento_id,indicador_id,competencia,ano,mes,versao_lancamento,tipo_observacao,observacao,
      fonte_documental,paginas_documento,sha256_observacao,sha256_documento_declarado,sha256_arquivo_fisico,
      documento_referencia,NULL,origem_registro FROM @carga;
    SET @linhasInseridas=@@ROWCOUNT;
    IF @linhasInseridas<>23 THROW 53513,N'Quantidade inserida diferente de 23.',1;
  END

  IF EXISTS(
    SELECT 1 FROM @carga c FULL JOIN (
      SELECT * FROM dbo.lancamentos_observacoes_documentais WHERE origem_registro=@migration
    ) d ON d.id=c.id
    WHERE c.id IS NULL OR d.id IS NULL OR d.lancamento_id<>c.lancamento_id OR d.indicador_id<>c.indicador_id
      OR d.competencia<>c.competencia OR d.ano<>c.ano OR d.mes<>c.mes OR d.versao_lancamento<>c.versao_lancamento
      OR d.tipo_observacao<>c.tipo_observacao OR d.observacao<>c.observacao OR d.fonte_documental<>c.fonte_documental
      OR d.paginas_documento<>c.paginas_documento OR d.sha256_observacao<>c.sha256_observacao
      OR d.sha256_documento_declarado<>c.sha256_documento_declarado OR d.sha256_arquivo_fisico<>c.sha256_arquivo_fisico
      OR d.documento_referencia<>c.documento_referencia OR d.substitui_observacao_id IS NOT NULL
  ) THROW 53514,N'Pos-condicao encontrou conteudo documental divergente.',1;

  IF EXISTS(
    SELECT 1 FROM @lancamentos_antes a JOIN dbo.lancamentos l ON l.id=a.id
    WHERE a.fingerprint<>HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),
      CAST(N'' AS NVARCHAR(MAX))+ISNULL(l.id,N'<NULL>')+N'|'+ISNULL(l.indicador_id,N'<NULL>')+N'|'+ISNULL(l.competencia,N'<NULL>')+
      N'|'+ISNULL(CONVERT(NVARCHAR(20),l.ano),N'<NULL>')+N'|'+ISNULL(CONVERT(NVARCHAR(20),l.mes),N'<NULL>')+
      N'|'+ISNULL(l.trimestre,N'<NULL>')+N'|'+ISNULL(l.plano,N'<NULL>')+N'|'+ISNULL(l.pilar,N'<NULL>')+
      N'|'+ISNULL(l.unidade_apuradora,N'<NULL>')+N'|'+ISNULL(l.diretoria_responsavel,N'<NULL>')+
      N'|'+ISNULL(l.dados_entrada_json,N'<NULL>')+N'|'+ISNULL(l.resultado_calculado,N'<NULL>')+
      N'|'+ISNULL(l.resultado_oficial,N'<NULL>')+N'|'+ISNULL(l.meta_referencia,N'<NULL>')+
      N'|'+ISNULL(l.percentual_atingido,N'<NULL>')+N'|'+ISNULL(l.situacao,N'<NULL>')+N'|'+ISNULL(l.status,N'<NULL>')+
      N'|'+ISNULL(l.observacao_unidade,N'<NULL>')+N'|'+ISNULL(l.referencia_evidencia,N'<NULL>')+
      N'|'+ISNULL(l.evidencia_id,N'<NULL>')+N'|'+CONVERT(NVARCHAR(20),l.versao_atual)+
      N'|'+ISNULL(l.usuario_responsavel,N'<NULL>')+N'|'+ISNULL(l.created_at,N'<NULL>')+N'|'+ISNULL(l.updated_at,N'<NULL>')
    ))
  ) THROW 53515,N'Snapshot historico de lancamento foi alterado.',1;
  IF @homologacoesAntes<>(SELECT h.* FROM dbo.homologacoes h JOIN @carga c ON c.lancamento_id=h.lancamento_id ORDER BY h.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @evidenciasAntes<>(SELECT e.* FROM dbo.evidencias e JOIN @carga c ON c.lancamento_id=e.lancamento_id ORDER BY e.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @retificacoesAntes<>(SELECT r.* FROM dbo.retificacoes r JOIN @carga c ON c.lancamento_id=r.lancamento_id ORDER BY r.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @reaberturasAntes<>(SELECT s.* FROM dbo.solicitacoes_reabertura s JOIN @carga c ON c.lancamento_id=s.lancamento_id ORDER BY s.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    OR @auditoriaAntes<>(SELECT a.* FROM dbo.auditoria a JOIN @carga c ON c.lancamento_id=a.entidade_id WHERE a.entidade=N'lancamentos' ORDER BY a.id FOR JSON PATH,INCLUDE_NULL_VALUES)
    THROW 53516,N'Governanca ou auditoria historica foi alterada.',1;

  DECLARE @marDepois NVARCHAR(MAX)=(
    SELECT d.* FROM dbo.lancamentos_observacoes_documentais d
    WHERE d.competencia=N'2026-03' AND d.ano=2026 AND d.mes=3
    ORDER BY d.id FOR JSON PATH,INCLUDE_NULL_VALUES
  );
  DECLARE @marHashDepois VARBINARY(32)=HASHBYTES('SHA2_256',CONVERT(VARBINARY(MAX),@marDepois));
  IF @marAntes<>@marDepois OR @marHashAntes<>@marHashDepois
    THROW 53517,N'Snapshot documental do 1TRI foi alterado.',1;
  IF (SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais)<>46
    OR (SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais WHERE competencia=N'2026-03' AND ano=2026 AND mes=3)<>23
    OR (SELECT COUNT(*) FROM dbo.lancamentos_observacoes_documentais WHERE competencia=N'2026-06' AND ano=2026 AND mes=6)<>23
    OR EXISTS(SELECT 1 FROM dbo.lancamentos_observacoes_documentais WHERE origem_registro=@migration AND substitui_observacao_id IS NOT NULL)
    THROW 53518,N'Pos-condicao quantitativa documental incompleta.',1;

  IF @transacaoPropria=1 COMMIT TRANSACTION;
  SELECT N'COMMIT' AS transacao,@linhasInseridas AS registros_criados,0 AS registros_alterados,0 AS registros_removidos,
    LOWER(CONVERT(VARCHAR(64),@marHashAntes,2)) AS hash_mar_antes,
    LOWER(CONVERT(VARCHAR(64),@marHashDepois,2)) AS hash_mar_depois,
    CASE WHEN @existentes=23 THEN N'JA APLICADA - SEM DML' ELSE N'23 OBSERVACOES DOCUMENTAIS CRIADAS' END AS resultado;
END TRY
BEGIN CATCH
  IF @transacaoPropria=1 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;
